use serde_json::{json,Value};use sha2::{Sha256,Digest};use std::{fs,path::Path,collections::BTreeMap,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/swiss-control-audit175";const P:&str="/home/ubuntu/src/zopro-perf-work/swiss-groups-sdk175";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn main(){let root=Path::new(R);let original=read(root.join("analysis.json"));let identities=read(format!("{P}/identities.json"));let mut results=BTreeMap::new();
for variant in["accepted","OFF","ON"]{let data=format!("{P}/perf/cycles-1x2-w32-{variant}.data");let out=Command::new("perf").args(["script","--header","--ns","-i",&data,"-F","pid,tid,time,period,ip,sym,symoff"]).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let text=String::from_utf8(out.stdout).unwrap();fs::write(root.join(format!("{variant}-time-offset.log")),&text).unwrap();let mut bins=BTreeMap::<u64,(u64,u64)>::new();let mut tids=BTreeMap::<String,(u64,u64)>::new();let mut total=0u64;let mut samples=0;let mut all_samples=0;let mut all_period=0u64;
for line in text.lines().filter(|l|!l.trim().is_empty()&&!l.trim().starts_with('#')){let f=line.split_whitespace().collect::<Vec<_>>();assert_eq!(f.len(),5);let period=f[2].parse::<u64>().unwrap();all_samples+=1;all_period+=period;if !f[4].contains("g2_borrowed5apply"){continue;}let(_,offset)=f[4].rsplit_once("+0x").unwrap();let offset=u64::from_str_radix(offset,16).unwrap();let bin=offset/256;let b=bins.entry(bin).or_default();b.0+=period;b.1+=1;let b=tids.entry(f[0].into()).or_default();b.0+=period;b.1+=1;total+=period;samples+=1;}
let old=&original["profiles"][format!("cycles-1x2-w32-{variant}")];assert_eq!(all_period,old["total_period"]);assert_eq!(all_samples,old["total_samples"].as_u64().unwrap());assert_eq!(total,old["categories"]["G2_stream"]["period"]);assert_eq!(samples,old["categories"]["G2_stream"]["samples"]);
results.insert(variant,json!({"raw_sha256":hash(&fs::read(&data).unwrap()),"G2_period":total,"G2_samples":samples,"all_samples":all_samples,"all_period":all_period,"bins256":bins.iter().map(|(b,(p,s))|(format!("0x{:x}",b*256),json!({"period":p,"samples":s,"share_of_G2":*p as f64/total as f64}))).collect::<BTreeMap<_,_>>(),"TIDs":tids}));}
// Cross-check the raw ELF extraction using an independent objcopy section dump.
let row=original["selected"].as_array().unwrap().iter().find(|r|r["class"]=="G2_stream").unwrap();let mut cross=BTreeMap::new();for v in["accepted","OFF"]{let binary=identities[v]["binary"].as_str().unwrap();let section=root.join(format!("{v}-text.bin"));assert!(Command::new("objcopy").arg(format!("--dump-section=.text={}",section.display())).arg(binary).arg(root.join(format!("{v}-objcopy-output.elf"))).status().unwrap().success());let elf=fs::read(binary).unwrap();let shoff=u64::from_le_bytes(elf[40..48].try_into().unwrap())as usize;let n=u16::from_le_bytes(elf[60..62].try_into().unwrap())as usize;let string_index=u16::from_le_bytes(elf[62..64].try_into().unwrap())as usize;let s=shoff+string_index*64;let string_offset=u64::from_le_bytes(elf[s+24..s+32].try_into().unwrap())as usize;let mut addr=None;for i in 0..n{let at=shoff+i*64;let name=u32::from_le_bytes(elf[at..at+4].try_into().unwrap())as usize;let string=&elf[string_offset+name..];let end=string.iter().position(|&b|b==0).unwrap();if &string[..end]==b".text"{addr=Some(u64::from_le_bytes(elf[at+16..at+24].try_into().unwrap()));}}let addr=addr.unwrap();let symbol_address=if v=="accepted"{row["accepted_address"].as_str().unwrap()}else{row["comparisons"][v]["address"].as_str().unwrap()};let start=(u64::from_str_radix(symbol_address,16).unwrap()-addr)as usize;let size=row["accepted_size"].as_u64().unwrap()as usize;let text=fs::read(&section).unwrap();let digest=hash(&text[start..start+size]);assert_eq!(digest,row["accepted_bytes_sha256"]);cross.insert(v,json!({"G2_size":size,"objcopy_slice_sha256":digest,"matches_ELF_parser":true}));}
let data=json!({"existing_profiles_only":true,"new_captures":0,"cpu_attribute_absent":true,"failed_cpu_decode_before_fallback":"Samples for cycles:u event do not have CPU attribute set; cannot print cpu field","profile_totals_exact_to_prior_decode":true,"profiles":results,"objcopy_crosscheck":cross});fs::write(root.join("offset-analysis.json"),serde_json::to_vec_pretty(&data).unwrap()).unwrap();for v in["accepted","OFF","ON"]{let p=&data["profiles"][v];let mut bins=p["bins256"].as_object().unwrap().iter().collect::<Vec<_>>();bins.sort_by(|a,b|b.1["period"].as_u64().unwrap().cmp(&a.1["period"].as_u64().unwrap()));println!("{v}:G2period{} samples{} TIDs{} top{}",p["G2_period"],p["G2_samples"],p["TIDs"].as_object().unwrap().len(),serde_json::to_string(&bins[..bins.len().min(5)]).unwrap());}
}
